<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
use Sentinel\Repositories\PermissionRepository;
final class OperationalAlertService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly PermissionRepository $permissions,private readonly IntegrationCentreService $integrations) {}
    private function recipient(string $user,string $site):bool {return (bool)$this->db->fetch("SELECT user_id FROM users WHERE company_id=:company AND user_id=:user AND status='ACTIVE'",['company'=>$this->company(),'user'=>$user])&&$this->permissions->userHasPermission($user,'operational_alerts.view')&&(!$this->permissions->userHasPermission($user,'site_scope.restricted')||(bool)$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND user_id=:user AND site_id=:site',['company'=>$this->company(),'user'=>$user,'site'=>$site]));}
    private function worker():?array {$r=$this->db->fetch("SELECT finished_at,state,summary FROM worker_runs WHERE company_id=:company AND worker_name='operations-hub' ORDER BY run_id DESC LIMIT 1",['company'=>$this->company()]);if($r&&$r['state']==='OK'&&$r['finished_at']<gmdate('Y-m-d H:i:s',time()-300))$r['state']='STALE';return $r;}
    public function workspace(array $input):array {$this->fields($input,['site_id']);$site=$this->access->requireSite($input['site_id']??null);$p=['company'=>$this->company(),'site'=>$site['site_id']];return ['worker'=>$this->worker(),'rule'=>$this->db->fetch('SELECT * FROM operational_alert_rules WHERE company_id=:company AND site_id=:site',$p),'alerts'=>$this->db->fetchAll('SELECT * FROM operational_alerts WHERE company_id=:company AND site_id=:site ORDER BY alert_id DESC LIMIT 500',$p),'queue_health'=>$this->db->fetchAll('SELECT user_id,pending_count,blocked_count,oldest_at,received_at FROM inspection_queue_health WHERE company_id=:company AND site_id=:site',$p),'note'=>'Queue counts are client-reported snapshots. Acknowledging an alert does not resolve its source. Recipients receive in-app notifications; use existing radio/phone escalation procedures.'];}
    public function health(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','pending_count','blocked_count','oldest_at']);$site=$this->access->requireSite($input['site_id']??null);$pending=$this->number($input['pending_count']??null,0,50);$blocked=$this->number($input['blocked_count']??null,0,$pending);$oldest=$pending?$this->at($input['oldest_at']??null):null;if($oldest!==null&&(strtotime($oldest.' UTC')>time()+120||strtotime($oldest.' UTC')<time()-366*86400))throw HttpException::unprocessable('Queue capture time is outside the supported range.');$keys=['company'=>$this->company(),'site'=>$site['site_id'],'actor'=>$this->actor()];$old=$this->db->fetch('SELECT health_id FROM inspection_queue_health WHERE company_id=:company AND site_id=:site AND user_id=:actor',$keys);$v=$keys+['pending'=>$pending,'blocked'=>$blocked,'oldest'=>$oldest,'now'=>gmdate('Y-m-d H:i:s')];if($old)$this->db->execute('UPDATE inspection_queue_health SET pending_count=:pending,blocked_count=:blocked,oldest_at=:oldest,received_at=:now WHERE company_id=:company AND site_id=:site AND user_id=:actor',$v);else $this->db->execute('INSERT INTO inspection_queue_health(company_id,site_id,user_id,pending_count,blocked_count,oldest_at,received_at) VALUES(:company,:site,:actor,:pending,:blocked,:oldest,:now)',$v);return ['received'=>true];});}
    public function rule(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','expected_revision','recipient_user_id','backup_user_id','queue_minutes','findings_hours','escalate_minutes','enabled']);$site=$this->access->requireSite($input['site_id']??null);$first=(string)$this->number($input['recipient_user_id']??null);$backup=(string)$this->number($input['backup_user_id']??null);if($first===$backup||!$this->recipient($first,(string)$site['site_id'])||!$this->recipient($backup,(string)$site['site_id'])||!is_bool($input['enabled']??null))throw HttpException::unprocessable('Choose two different active recipients with alert and site access.');$keys=['company'=>$this->company(),'site'=>$site['site_id']];$old=$this->db->fetch('SELECT revision FROM operational_alert_rules WHERE company_id=:company AND site_id=:site',$keys);if($this->number($input['expected_revision']??null,0)!==(int)($old['revision']??0))throw HttpException::conflict('Alert rule changed.');$v=$keys+['first'=>$first,'backup'=>$backup,'queue'=>$this->number($input['queue_minutes']??null,1,1440),'findings'=>$this->number($input['findings_hours']??null,1,720),'escalate'=>$this->number($input['escalate_minutes']??null,1,1440),'enabled'=>(int)$input['enabled']];if($old)$this->db->execute('UPDATE operational_alert_rules SET recipient_user_id=:first,backup_user_id=:backup,queue_minutes=:queue,findings_hours=:findings,escalate_minutes=:escalate,enabled=:enabled,revision=revision+1 WHERE company_id=:company AND site_id=:site',$v);else $this->db->execute('INSERT INTO operational_alert_rules(company_id,site_id,recipient_user_id,backup_user_id,queue_minutes,findings_hours,escalate_minutes,enabled) VALUES(:company,:site,:first,:backup,:queue,:findings,:escalate,:enabled)',$v);$this->audit->record('operational_alert_rule','saved',(string)$site['site_id']);return ['saved'=>true];});}
    public function acknowledge(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$r=$this->row('operational_alerts','alert_id',$id);$this->access->requireSite($r['site_id']);if($r['state']!=='OPEN'||$this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Alert changed or is already acknowledged.');$this->db->execute("UPDATE operational_alerts SET state='ACKNOWLEDGED',revision=revision+1,acknowledged_at=:now,acknowledged_by_user_id=:actor WHERE company_id=:company AND alert_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'company'=>$this->company(),'id'=>$id]);$this->audit->record('operational_alert','acknowledged',$id);return ['acknowledged'=>true];});}
    private function notify(array $alert,string $user,string $stage):bool {if(!$this->recipient($user,(string)$alert['site_id']))return false;$p=['company'=>$this->company(),'alert'=>$alert['alert_id'],'episode'=>$alert['episode'],'stage'=>$stage,'user'=>$user];if($this->db->fetch('SELECT delivery_id FROM operational_alert_deliveries WHERE company_id=:company AND alert_id=:alert AND episode=:episode AND stage=:stage AND recipient_user_id=:user',$p))return false;$now=gmdate('Y-m-d H:i:s');$this->db->execute('INSERT INTO notifications(company_id,recipient_user_id,event_type,severity,title,message) VALUES(:company,:user,:type,:severity,:title,:message)',['company'=>$this->company(),'user'=>$user,'type'=>$alert['alert_type'],'severity'=>'HIGH','title'=>$stage==='BACKUP'?'Escalated operational alert':'Operational alert','message'=>$alert['message']]);$this->db->execute('INSERT INTO operational_alert_deliveries(company_id,alert_id,episode,stage,recipient_user_id,delivered_at) VALUES(:company,:alert,:episode,:stage,:user,:now)',$p+['now'=>$now]);return true;}
    public function tick():array {return $this->atomic(function(){$rules=$this->db->fetchAll('SELECT * FROM operational_alert_rules WHERE company_id=:company AND enabled=1 ORDER BY rule_id LIMIT 101',['company'=>$this->company()]);if(count($rules)>100)throw HttpException::unprocessable('More than 100 enabled rules; narrow this worker.');$created=0;$resolved=0;$notified=0;$skipped=0;$now=gmdate('Y-m-d H:i:s');foreach($rules as$rule){$site=(string)$rule['site_id'];if(!$this->access->allowed($site))continue;$this->access->requireSite($site);$candidates=[];$base=['company'=>$this->company(),'site'=>$site];$health=$this->db->fetchAll('SELECT * FROM inspection_queue_health WHERE company_id=:company AND site_id=:site AND pending_count>0 LIMIT 501',$base);$keys=$this->db->fetchAll("SELECT l.loan_id,l.due_at,a.asset_code FROM custody_loans l JOIN custody_assets a ON a.company_id=l.company_id AND a.asset_id=l.asset_id WHERE l.company_id=:company AND a.site_id=:site AND l.state IN ('PENDING_ACCEPTANCE','ISSUED','RETURN_PENDING') AND l.due_at<:now LIMIT 501",$base+['now'=>$now]);$drills=$this->db->fetchAll("SELECT exercise_id,closed_at FROM emergency_exercises WHERE company_id=:company AND site_id=:site AND state='CLOSED_WITH_FINDINGS' AND closed_at<=:deadline LIMIT 501",$base+['deadline'=>gmdate('Y-m-d H:i:s',time()-(int)$rule['findings_hours']*3600)]);if(count($health)>500||count($keys)>500||count($drills)>500)throw HttpException::unprocessable('Too many alert sources; review site data before continuing.');
        foreach($health as$h)if($h['blocked_count']>0||$h['oldest_at']<=gmdate('Y-m-d H:i:s',time()-(int)$rule['queue_minutes']*60)){$stale=$h['received_at']<gmdate('Y-m-d H:i:s',time()-1800);$candidates['queue:'.$site.':'.$h['user_id']]=['QUEUE_PENDING','Inspection queue for user #'.$h['user_id'].' last reported '.$h['pending_count'].' pending, '.$h['blocked_count'].' needing review. '.($stale?'Contact is stale; current queue status is unknown.':'Review upload progress.'). ' Report received '.$h['received_at'].' UTC.'];}
        foreach($keys as$k)$candidates['key:'.$k['loan_id']]=['KEY_OVERDUE','Key/card '.$k['asset_code'].' loan #'.$k['loan_id'].' is overdue since '.$k['due_at'].' UTC.'];foreach($drills as$d)$candidates['drill:'.$d['exercise_id']]=['DRILL_FINDINGS','Drill #'.$d['exercise_id'].' ended with findings. Review its debrief and complete follow-up.'];
        foreach($candidates as$source=>[$type,$message]){$r=$this->db->fetch('SELECT * FROM operational_alerts WHERE company_id=:company AND source_key=:source',['company'=>$this->company(),'source'=>$source]);if(!$r){$this->db->execute('INSERT INTO operational_alerts(company_id,site_id,source_key,alert_type,message,opened_at,last_seen_at) VALUES(:company,:site,:source,:type,:message,:now,:seen)',$base+['source'=>$source,'type'=>$type,'message'=>$message,'now'=>$now,'seen'=>$now]);$r=$this->row('operational_alerts','alert_id',(string)$this->db->connection()->lastInsertId());$created++;$this->integrations->event($site,'operational_alert.opened',['alert_id'=>$r['alert_id'],'type'=>$type]);}elseif($r['state']==='RESOLVED'){$this->db->execute("UPDATE operational_alerts SET state='OPEN',episode=episode+1,revision=revision+1,opened_at=:now,last_seen_at=:seen,resolved_at=NULL,acknowledged_at=NULL,acknowledged_by_user_id=NULL,message=:message WHERE company_id=:company AND alert_id=:id",['now'=>$now,'seen'=>$now,'message'=>$message,'company'=>$this->company(),'id'=>$r['alert_id']]);$r=$this->row('operational_alerts','alert_id',(string)$r['alert_id']);$created++;}else $this->db->execute('UPDATE operational_alerts SET last_seen_at=:now,message=:message WHERE company_id=:company AND alert_id=:id',['now'=>$now,'message'=>$message,'company'=>$this->company(),'id'=>$r['alert_id']]);$r['message']=$message;if($r['state']==='OPEN'){if($this->notify($r,(string)$rule['recipient_user_id'],'PRIMARY'))$notified++;elseif(!$this->recipient((string)$rule['recipient_user_id'],$site))$skipped++;if($r['opened_at']<=gmdate('Y-m-d H:i:s',time()-(int)$rule['escalate_minutes']*60)&&$this->notify($r,(string)$rule['backup_user_id'],'BACKUP'))$notified++;}}
        foreach($this->db->fetchAll("SELECT alert_id,source_key FROM operational_alerts WHERE company_id=:company AND site_id=:site AND state<>'RESOLVED'",$base)as$r)if(!isset($candidates[$r['source_key']])){$this->db->execute("UPDATE operational_alerts SET state='RESOLVED',revision=revision+1,resolved_at=:now WHERE company_id=:company AND alert_id=:id",['now'=>$now,'company'=>$this->company(),'id'=>$r['alert_id']]);$resolved++;}
        }$this->audit->record('operational_alert','worker_completed',null,[],[],['created'=>$created,'resolved'=>$resolved,'notifications'=>$notified,'recipients_without_access'=>$skipped]);return ['created'=>$created,'resolved'=>$resolved,'notifications'=>$notified,'recipients_without_access'=>$skipped];});}
}
